"""Few-Shot Memory - baseline using all training examples as demonstrations.

Accumulates (raw_question, ground_truth) pairs during training, uses them as
few-shot context at test time. Uses raw questions (not full preprocessed prompts)
to avoid repeating task context per example — matching MCE reproduce behavior.

Variant:
- FewShotAll: Up to 9999 examples
Uses a global max_chars=50000 cap (matching MCE reproduce).
"""

import hashlib
import json
import random
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field

PROMPT_TEMPLATE = """Solve the problem below based on the examples provided.

{examples_section}

**Problem:**
{input}

**Instructions:**
- Follow the patterns shown in the examples above
- Respond in JSON format

{{"reasoning": "[your reasoning]", "final_answer": "[your answer]"}}"""

MAX_CHARS = 30000


def _seed_for_input(input: str) -> int:
    """Return a stable per-input seed across Python processes."""
    return int.from_bytes(hashlib.sha256(input.encode()).digest()[:8], "big")


class FewShotMemory(MemorySystem):
    """Few-shot baseline - accumulate all examples, use as demonstrations."""

    def __init__(
        self,
        llm: LLMCallable,
        max_examples: int = 50,
    ):
        super().__init__(llm)
        self.max_examples = max_examples
        self.examples: list[dict[str, str]] = []

    def _format_examples_section(self, seed: int | None = None) -> str:
        """Format examples as few-shot demonstrations, respecting global char limit.

        Uses raw_question (short Q/A) when available to avoid repeating task
        context per example. Falls back to full input for non-MCE datasets.

        Args:
            seed: If provided, randomly sample max_examples and shuffle order.
                  Each eval instance should pass a different seed for diversity.
        """
        if not self.examples:
            return ""

        if seed is not None and len(self.examples) > self.max_examples:
            rng = random.Random(seed)
            to_use = rng.sample(self.examples, self.max_examples)
        else:
            to_use = self.examples[-self.max_examples :]
            if seed is not None:
                rng = random.Random(seed)
                to_use = list(to_use)
                rng.shuffle(to_use)

        parts = []
        total_chars = 0
        for ex in to_use:
            # Use raw_question for demos (avoids repeating task context per example)
            question = ex.get("raw_question", ex["input"])
            part = f"Q: {question}\nA: {ex['target']}"
            if total_chars + len(part) > MAX_CHARS:
                break
            parts.append(part)
            total_chars += len(part) + 2  # \n\n separator

        return "\n\n".join(parts)

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        """Generate prediction using accumulated few-shot examples."""
        seed = _seed_for_input(input)
        examples_section = self._format_examples_section(seed=seed)
        prompt = PROMPT_TEMPLATE.format(
            examples_section=examples_section,
            input=input,
        )

        response = self.call_llm(prompt)
        answer = extract_json_field(response, "final_answer")

        return answer, {
            "full_response": response,
            "num_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        """Accumulate all examples with ground truth labels."""
        for r in batch_results:
            ex = {"input": r["input"], "target": r["ground_truth"]}
            if "raw_question" in r:
                ex["raw_question"] = r["raw_question"]
            self.examples.append(ex)

    def get_context_length(self) -> int:
        """Return length of the examples section actually injected per query."""
        return len(self._format_examples_section())

    def get_state(self) -> str:
        """Serialize memory state."""
        return json.dumps({"examples": self.examples}, indent=2)

    def set_state(self, state: str) -> None:
        """Restore memory state from JSON."""
        data = json.loads(state)
        self.examples = data.get("examples", [])
"""Query-conditioned few-shot retrieval with a fixed context budget."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Use the related examples as demonstrations. Their answers are labeled feedback.

{examples}

Problem:
{input}

Follow the problem's own instructions and return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> list[str]:
    features: list[str] = []
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            features.extend(run[i : i + 2] for i in range(len(run) - 1))
            features.extend(run[i : i + 3] for i in range(len(run) - 2))
        else:
            features.append(run)
    return features


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1500) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Select demonstrations by query similarity rather than recency or order."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 14000
        self._last_context_len = 0

    def _retrieve(self, query: str, limit: int = 14) -> list[dict[str, str]]:
        if not self.examples:
            return []
        docs = [_features(ex["input"]) for ex in self.examples]
        doc_freq: Counter[str] = Counter()
        for doc in docs:
            doc_freq.update(set(doc))
        avg_len = sum(map(len, docs)) / max(1, len(docs))
        qtf = Counter(_features(query))
        n_docs = len(docs)
        ranked: list[tuple[float, int]] = []
        for index, doc in enumerate(docs):
            tf = Counter(doc)
            score = 0.0
            for term, q_count in qtf.items():
                term_count = tf.get(term, 0)
                if not term_count:
                    continue
                df = doc_freq[term]
                idf = math.log(1.0 + (n_docs - df + 0.5) / (df + 0.5))
                denom = term_count + 1.2 * (
                    0.25 + 0.75 * len(doc) / max(1.0, avg_len)
                )
                score += min(q_count, 2) * idf * term_count * 2.2 / denom
            ranked.append((score, index))
        ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return [self.examples[index] for _, index in ranked[:limit]]

    def _format_examples(self, query: str) -> str:
        selected = self._retrieve(query)
        parts: list[str] = []
        used = 0
        for example in selected:
            part = f"Q: {_clip(example['input'])}\nA: {example['target']}"
            remaining = self.context_budget - used
            if remaining <= 0:
                break
            if len(part) > remaining:
                if remaining < 80:
                    break
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context_len = used
        return "\n\n".join(parts) or "No learned examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "retrieved_examples": 0 if examples == "No learned examples yet." else len(self._retrieve(input)),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {"input": _source_text(row), "target": str(row["ground_truth"])}
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])

"""Retrieve complete labeled examples while discounting repeated vocabulary."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Use the relevant labeled examples as demonstrations. Repeated wording may be boilerplate; match the substantive content and follow the current problem's instructions.

{examples}

Current problem:
{input}

Return JSON with a concise final_answer, preserving the answer form requested by the problem.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]}}"""


def _features(text: str) -> list[str]:
    result: list[str] = []
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.extend(run[i : i + 2] for i in range(len(run) - 1))
            result.extend(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result.append(run)
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1350) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Query-conditioned BM25 retrieval with explicit boilerplate discounting."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 12500
        self.max_examples = 14
        self._last_context = ""

    def _rank(self, query: str) -> list[tuple[float, int]]:
        if not self.examples:
            return []
        documents = [_features(example["input"]) for example in self.examples]
        document_frequency: Counter[str] = Counter()
        for document in documents:
            document_frequency.update(set(document))
        count = len(documents)
        average_length = sum(map(len, documents)) / max(1, count)
        query_counts = Counter(_features(query))
        ranked: list[tuple[float, int]] = []
        for index, document in enumerate(documents):
            term_counts = Counter(document)
            score = 0.0
            for token, query_count in query_counts.items():
                frequency = document_frequency.get(token, 0)
                term_count = term_counts.get(token, 0)
                if not frequency or not term_count:
                    continue
                # Near-universal terms contribute little; the hard taper also
                # prevents repeated prompt boilerplate from dominating matches.
                prevalence = frequency / count
                if prevalence >= 0.92:
                    continue
                idf = math.log(1.0 + (count - frequency + 0.5) / (frequency + 0.5))
                idf *= max(0.08, 1.0 - prevalence**2)
                denominator = term_count + 1.2 * (
                    0.25 + 0.75 * len(document) / max(1.0, average_length)
                )
                score += min(query_count, 2) * idf * term_count * 2.2 / denominator
            ranked.append((score, index))
        ranked.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return ranked

    def _format_examples(self, query: str) -> str:
        parts: list[str] = []
        used = 0
        ranked = self._rank(query)
        selected = [index for _, index in ranked[: self.max_examples]]
        for index in selected:
            example = self.examples[index]
            part = f"Q: {_clip(example['input'])}\nA: {example['target']}"
            remaining = self.context_budget - used
            if remaining < 100:
                break
            if len(part) > remaining:
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context = "\n\n".join(parts)
        return self._last_context or "No learned examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
