"""Similarity-gated replay of prior errors as corrected contrastive examples."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """Learn from the feedback examples below. In every correction, the model answer is known to be wrong and the corrected answer is authoritative. Use a similar correction to avoid repeating its mistake. The examples are guidance; follow the current problem's instructions.

{memory}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> set[str]:
    result: set[str] = set()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result.add(run)
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 1050) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Store feedback outcomes and retrieve the most relevant corrections."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, Any]] = []
        self.context_budget = 9000
        self._last_context_len = 0

    def _rank(self, query: str, rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
        if not rows:
            return []
        query_features = _features(query)
        if not query_features:
            return rows[-5:][::-1]
        row_features = [_features(row["input"]) for row in rows]
        df: Counter[str] = Counter()
        for features in row_features:
            df.update(features)
        n_rows = len(rows)
        weights = {
            token: math.log(1.0 + (n_rows - df[token] + 0.5) / (df[token] + 0.5))
            for token in query_features
        }
        denom = sum(weights.values()) or 1.0
        scores = [
            (sum(weights[token] for token in query_features & features) / denom, i)
            for i, features in enumerate(row_features)
        ]
        scores.sort(key=lambda item: (item[0], item[1]), reverse=True)
        return [rows[i] for score, i in scores[:6] if score > 0]

    def _format_memory(self, query: str) -> str:
        failures = [row for row in self.examples if not row["was_correct"]]
        successes = [row for row in self.examples if row["was_correct"]]
        corrections = self._rank(query, failures)
        anchors = self._rank(query, successes)[:2]
        parts: list[str] = []
        used = 0
        for row in corrections:
            bad = _clip(str(row.get("prediction", "")), 180)
            part = (
                f"Similar case: {_clip(row['input'])}\n"
                f"Known wrong model answer: {bad}\n"
                f"Corrected answer: {row['target']}"
            )
            if used + len(part) > self.context_budget:
                continue
            parts.append(part)
            used += len(part) + 2
        for row in anchors:
            part = f"Related labeled case: {_clip(row['input'], 700)}\nAnswer: {row['target']}"
            if used + len(part) > self.context_budget:
                continue
            parts.append(part)
            used += len(part) + 2
        self._last_context_len = used
        return "\n\n".join(parts) or "No feedback examples yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        memory = self._format_memory(input)
        response = self.call_llm(_PROMPT.format(memory=memory, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {
            "full_response": response,
            "correction_examples": sum(not row["was_correct"] for row in self.examples),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {
                    "input": _source_text(row),
                    "prediction": str(row.get("prediction", "")),
                    "target": str(row["ground_truth"]),
                    "was_correct": bool(row.get("was_correct", False)),
                }
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])

"""Retrieve pairs of similar cases whose verified answers differ."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """The labeled cases are selected because they resemble the current problem. Some similar cases have different verified answers, so compare the facts that distinguish them. The answers below are ground truth; previous model guesses are not included. Follow the current problem's own instructions.

{examples}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]}}"""


def _features(text: str) -> Counter[str]:
    result: Counter[str] = Counter()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result[run] += 1
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 900) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(token, 0.0) for token, value in left.items())


class Candidate(MemorySystem):
    """Build query-relevant, ground-truth-only boundary pairs at prediction time."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self.context_budget = 7600
        self.max_pairs = 3
        self._last_context = ""

    def _vectors(self) -> tuple[list[dict[str, float]], dict[str, float]]:
        documents = [_features(example["input"]) for example in self.examples]
        frequency: Counter[str] = Counter()
        for document in documents:
            frequency.update(document.keys())
        count = len(documents)
        inverse = {
            token: math.log(1.0 + (count + 1) / (value + 1))
            for token, value in frequency.items()
        }
        vectors: list[dict[str, float]] = []
        for document in documents:
            total = sum(document.values()) or 1
            raw = {token: value / total * inverse[token] for token, value in document.items()}
            norm = math.sqrt(sum(value * value for value in raw.values())) or 1.0
            vectors.append({token: value / norm for token, value in raw.items()})
        return vectors, inverse

    def _select_pairs(self, query: str) -> list[tuple[int, int]]:
        if len(self.examples) < 2:
            return []
        vectors, inverse = self._vectors()
        query_counts = _features(query)
        query_raw = {token: value * inverse.get(token, 0.0) for token, value in query_counts.items()}
        norm = math.sqrt(sum(value * value for value in query_raw.values())) or 1.0
        query_vector = {token: value / norm for token, value in query_raw.items()}
        query_scores = [_cosine(query_vector, vector) for vector in vectors]
        pairs: list[tuple[float, int, int]] = []
        for left in range(len(self.examples)):
            for right in range(left + 1, len(self.examples)):
                if self.examples[left]["target"] == self.examples[right]["target"]:
                    continue
                both = min(query_scores[left], query_scores[right])
                if both <= 0:
                    continue
                pair_similarity = _cosine(vectors[left], vectors[right])
                score = 0.65 * both + 0.35 * (query_scores[left] + query_scores[right]) / 2
                score += 0.20 * pair_similarity
                pairs.append((score, left, right))
        pairs.sort(reverse=True)
        selected: list[tuple[int, int]] = []
        used: set[int] = set()
        for _, left, right in pairs:
            if left in used or right in used:
                continue
            selected.append((left, right))
            used.update((left, right))
            if len(selected) >= self.max_pairs:
                break
        if not selected:
            nearest = sorted(range(len(self.examples)), key=lambda i: (query_scores[i], i), reverse=True)
            if len(nearest) >= 2:
                selected.append((nearest[0], nearest[1]))
        return selected

    def _format_examples(self, query: str) -> str:
        parts: list[str] = []
        used = 0
        for pair_number, (left, right) in enumerate(self._select_pairs(query), start=1):
            first, second = self.examples[left], self.examples[right]
            part = (
                f"Similar case pair {pair_number}:\n"
                f"Case A: {_clip(first['input'])}\nVerified answer A: {first['target']}\n"
                f"Case B: {_clip(second['input'])}\nVerified answer B: {second['target']}"
            )
            remaining = self.context_budget - used
            if remaining < 150:
                break
            if len(part) > remaining:
                part = part[: remaining - 3] + "..."
            parts.append(part)
            used += len(part) + 2
        self._last_context = "\n\n".join(parts)
        return self._last_context or "No paired examples are available yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "retrieved_pairs": self._last_context.count("Similar case pair"),
            "memory_examples": len(self.examples),
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {(example["input"], example["target"]) for example in self.examples}
        for row in batch_results:
            item = {"input": _source_text(row), "target": str(row["ground_truth"])}
            key = (item["input"], item["target"])
            if key not in seen:
                self.examples.append(item)
                seen.add(key)

    def get_context_length(self) -> int:
        return len(self._last_context)

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
        self._last_context = ""
"""Store labeled sentence fragments and retrieve evidence-sized excerpts."""

import json
import math
import re
from collections import Counter
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """The learned examples are partial text excerpts selected for overlap with the current problem. Use them as evidence, while remembering that each excerpt omits surrounding details. Follow the current problem's own instructions.

{examples}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]}}"""


def _features(text: str) -> Counter[str]:
    result: Counter[str] = Counter()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result[run] += 1
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _split_fragments(text: str) -> list[str]:
    sentences = re.split(r"(?<=[。！？.!?；;])\s*|\r?\n+", text)
    fragments: list[str] = []
    for sentence in sentences:
        sentence = " ".join(sentence.split())
        if len(sentence) < 35:
            continue
        if len(sentence) <= 620:
            fragments.append(sentence)
            continue
        # Long sentences become smaller evidence units without losing order.
        for piece in re.split(r"(?<=[，,])\s*", sentence):
            piece = piece.strip()
            if len(piece) >= 35:
                fragments.append(piece[:620])
    return fragments


def _clip(text: str, limit: int = 560) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


def _cosine(left: dict[str, float], right: dict[str, float]) -> float:
    if len(left) > len(right):
        left, right = right, left
    return sum(value * right.get(token, 0.0) for token, value in left.items())


class Candidate(MemorySystem):
    """Represent examples as query-matchable fragments rather than whole cases."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.fragments: list[dict[str, Any]] = []
        self._next_source_id = 0
        self.context_budget = 7600
        self.max_sources = 12
        self._last_context = ""

    def _vectors(self) -> tuple[list[dict[str, float]], dict[str, float]]:
        documents = [_features(fragment["text"]) for fragment in self.fragments]
        frequency: Counter[str] = Counter()
        source_features: dict[int, set[str]] = {}
        for fragment, document in zip(self.fragments, documents):
            source_features.setdefault(fragment["source_id"], set()).update(document.keys())
        for tokens in source_features.values():
            frequency.update(tokens)
        count = len(source_features)
        inverse = {
            token: math.log(1.0 + (count + 1) / (value + 1))
            for token, value in frequency.items()
        }
        vectors: list[dict[str, float]] = []
        for document in documents:
            total = sum(document.values()) or 1
            raw = {token: value / total * inverse[token] for token, value in document.items()}
            norm = math.sqrt(sum(value * value for value in raw.values())) or 1.0
            vectors.append({token: value / norm for token, value in raw.items()})
        return vectors, inverse

    def _format_examples(self, query: str) -> str:
        if not self.fragments:
            self._last_context = ""
            return "No learned excerpts yet."
        vectors, inverse = self._vectors()
        counts = _features(query)
        raw = {token: value * inverse.get(token, 0.0) for token, value in counts.items()}
        norm = math.sqrt(sum(value * value for value in raw.values())) or 1.0
        query_vector = {token: value / norm for token, value in raw.items()}
        ranked = sorted(
            ((_cosine(query_vector, vector), index) for index, vector in enumerate(vectors)),
            reverse=True,
        )
        parts: list[str] = []
        used = 0
        sources: set[int] = set()
        for score, index in ranked:
            fragment = self.fragments[index]
            if score <= 0 or fragment["source_id"] in sources:
                continue
            part = f"Related excerpt: {_clip(fragment['text'])}\nVerified answer: {fragment['target']}"
            remaining = self.context_budget - used
            if remaining < 100:
                break
            if len(part) > remaining:
                part = part[: remaining - 3] + "..."
            parts.append(part)
            sources.add(fragment["source_id"])
            used += len(part) + 2
            if len(sources) >= self.max_sources:
                break
        self._last_context = "\n\n".join(parts)
        return self._last_context or "No overlapping learned excerpts yet."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        examples = self._format_examples(input)
        response = self.call_llm(_PROMPT.format(examples=examples, input=input))
        return extract_json_field(response, "final_answer"), {
            "full_response": response,
            "retrieved_excerpts": len(self._last_context.split("\n\n")) if self._last_context else 0,
            "memory_sources": self._next_source_id,
        }

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        seen = {
            (fragment["source_id"], fragment["text"])
            for fragment in self.fragments
        }
        for row in batch_results:
            text = _source_text(row)
            target = str(row["ground_truth"])
            source_id = self._next_source_id
            self._next_source_id += 1
            for fragment_text in _split_fragments(text)[:80]:
                key = (source_id, fragment_text)
                if key not in seen:
                    self.fragments.append(
                        {"source_id": source_id, "text": fragment_text, "target": target}
                    )
                    seen.add(key)

    def get_context_length(self) -> int:
        return len(self._last_context)

    def get_state(self) -> str:
        return json.dumps(
            {"fragments": self.fragments, "next_source_id": self._next_source_id},
            ensure_ascii=False,
        )

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.fragments = data.get("fragments", [])
        self._next_source_id = data.get(
            "next_source_id",
            max((item.get("source_id", -1) for item in self.fragments), default=-1) + 1,
        )
        self._last_context = ""
"""Compact answer-pattern profiles learned from labeled examples."""

import json
import math
import re
from collections import Counter, defaultdict
from typing import Any

from ..llm import LLMCallable
from ..memory_system import MemorySystem, extract_json_field


_RUNS = re.compile(r"[\u3400-\u9fff]+|[a-zA-Z0-9]+")
_CJK = re.compile(r"^[\u3400-\u9fff]+$")
_PROMPT = """The learned answer patterns below summarize feedback from prior examples. Use them as candidate guidance, then inspect the current problem and follow its instructions. An answer may contain one or several output labels; do not omit a supported part.

{profiles}

Current problem:
{input}

Return JSON with a concise final_answer.
{{"reasoning": "[brief reasoning]", "final_answer": "[answer]"}}"""


def _features(text: str) -> Counter[str]:
    result: Counter[str] = Counter()
    for run in _RUNS.findall(text.lower()):
        if _CJK.match(run):
            result.update(run[i : i + 2] for i in range(len(run) - 1))
            result.update(run[i : i + 3] for i in range(len(run) - 2))
        else:
            result[run] += 1
    return result


def _source_text(row: dict[str, Any]) -> str:
    metadata = row.get("metadata")
    metadata = metadata if isinstance(metadata, dict) else {}
    return str(
        row.get("raw_question")
        or metadata.get("raw_question")
        or metadata.get("question")
        or row.get("input", "")
    )


def _clip(text: str, limit: int = 600) -> str:
    text = " ".join(text.split())
    if len(text) <= limit:
        return text
    head = int(limit * 0.72)
    return text[:head] + " … " + text[-(limit - head - 3) :]


class Candidate(MemorySystem):
    """Represent training feedback as answer profiles with supporting cases."""

    def __init__(self, llm: LLMCallable):
        super().__init__(llm)
        self.examples: list[dict[str, str]] = []
        self._last_context_len = 0
        self.profile_budget = 8500

    def _profiles(self, query: str) -> str:
        if not self.examples:
            self._last_context_len = 0
            return "No learned answer patterns yet."

        docs = [_features(row["input"]) for row in self.examples]
        document_frequency: Counter[str] = Counter()
        for doc in docs:
            document_frequency.update(doc.keys())
        count = len(docs)
        idf = {
            token: math.log(1.0 + (count + 1) / (frequency + 1))
            for token, frequency in document_frequency.items()
        }

        doc_vectors: list[dict[str, float]] = []
        query_counts = _features(query)
        query_vector = {
            token: value * idf.get(token, 0.0) for token, value in query_counts.items()
        }
        query_norm = math.sqrt(sum(value * value for value in query_vector.values())) or 1.0
        query_vector = {token: value / query_norm for token, value in query_vector.items()}

        class_vectors: dict[str, dict[str, float]] = defaultdict(lambda: defaultdict(float))
        class_counts: Counter[str] = Counter()
        for row, doc in zip(self.examples, docs):
            raw_total = sum(doc.values()) or 1
            vector = {
                token: value / raw_total * idf.get(token, 0.0)
                for token, value in doc.items()
            }
            norm = math.sqrt(sum(value * value for value in vector.values())) or 1.0
            vector = {token: value / norm for token, value in vector.items()}
            doc_vectors.append(vector)
            label = row["target"]
            class_counts[label] += 1
            for token, value in vector.items():
                class_vectors[label][token] += value

        prototypes: dict[str, dict[str, float]] = {}
        for label, vector in class_vectors.items():
            averaged = {token: value / class_counts[label] for token, value in vector.items()}
            norm = math.sqrt(sum(value * value for value in averaged.values())) or 1.0
            prototypes[label] = {token: value / norm for token, value in averaged.items()}

        class_scores = []
        for label, vector in prototypes.items():
            score = sum(query_vector.get(token, 0.0) * value for token, value in vector.items())
            class_scores.append((score, label))
        class_scores.sort(key=lambda item: (item[0], class_counts[item[1]], item[1]), reverse=True)

        cards: list[str] = []
        used = 0
        for score, label in class_scores[:8]:
            best_index = max(
                (index for index, row in enumerate(self.examples) if row["target"] == label),
                key=lambda index: sum(
                    query_vector.get(token, 0.0) * value
                    for token, value in doc_vectors[index].items()
                ),
            )
            support = _clip(self.examples[best_index]["input"])
            card = (
                f"Observed answer pattern: {label} "
                f"(support={class_counts[label]}, profile_match={score:.3f})\n"
                f"Closest supporting case: {support}"
            )
            if used + len(card) > self.profile_budget:
                continue
            cards.append(card)
            used += len(card) + 2
        self._last_context_len = used
        return "\n\n".join(cards) or "No matching answer profiles."

    def predict(self, input: str) -> tuple[str, dict[str, Any]]:
        profiles = self._profiles(input)
        response = self.call_llm(_PROMPT.format(profiles=profiles, input=input))
        answer = extract_json_field(response, "final_answer")
        return answer, {"full_response": response, "answer_patterns": len(self.examples)}

    def learn_from_batch(self, batch_results: list[dict[str, Any]]) -> None:
        for row in batch_results:
            self.examples.append(
                {"input": _source_text(row), "target": str(row["ground_truth"])}
            )

    def get_context_length(self) -> int:
        return self._last_context_len

    def get_state(self) -> str:
        return json.dumps({"examples": self.examples}, ensure_ascii=False)

    def set_state(self, state: str) -> None:
        data = json.loads(state)
        self.examples = data.get("examples", [])
